// ================================================================
//            PROVIDED TEST HARNESS -- DO NOT EDIT THIS FILE
// ================================================================
// ./task3.out read ROLL WORD...  run the words on the cache of ROLL, in order, and print what happens:
//                                 ADDR reads it, rm1 ADDR / rm2 ADDR remove its line from L1 / L2,
//                                 reset empties the cache. ROLL may be demo (an example cache).
// ./task3.out a                  print what part_a() returns
// ./task3.out info ROLL          run get_cache_info on the cache of ROLL (or demo)
// ./task3.out probe_parta ROLL   run your probe_parta (any access pattern you like) on the cache of ROLL
// ./task3.out                    tests: reads a field name and 8 parameters (as for make_part_b) from
//                                 standard input, runs get_cache_info on that cache, prints that field
// ./task3.out count-removes      the same input; prints how many remove_from_l1/l2 calls it made (Part c)
#include "cache.h"
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <exception>
#include <iostream>
#include <stdexcept>
#include <string>

// get_cache_info gets this wrapper, which counts the reads and the removes and passes everything on.
struct counting_cache : cache {
    cache* inner;
    unsigned long long reads = 0, removes = 0;
    explicit counting_cache(cache* c) : inner(c) {}
    std::uint16_t read(std::uint32_t addr) noexcept override { ++reads; return inner->read(addr); }
    void reset() noexcept override { inner->reset(); }
    void remove_from_l1(std::uint32_t addr) noexcept override { ++removes; inner->remove_from_l1(addr); }
    void remove_from_l2(std::uint32_t addr) noexcept override { ++removes; inner->remove_from_l2(addr); }
};

// Part B: runs your eight functions in the order of find_order (in cache_info.cpp). Each may read the
// fields found by the functions before it (the others are still 0), and each starts from an empty cache.
cache_info get_cache_info(cache* c) {
    finder const all[8] = {find_l1_latency, find_l2_latency, find_dram_latency, find_line_size,
                           find_l1_num_way, find_l1_cache_size, find_l2_num_way, find_l2_cache_size};
    for (finder f : all) { // find_order must hold each of these exactly once
        int times = 0;
        for (finder g : find_order) times += g == f;
        if (times != 1) throw std::runtime_error("find_order must name each of the eight find_ functions exactly once");
    }

    cache_info info{};
    for (finder f : find_order) {
        c->reset(); // every function starts from an empty cache
        f(c, info);
    }
    return info;
}

static std::unique_ptr<cache> make_named(const std::string& roll) {
    if (roll == "demo") return make_part_b(64, 16, 4, 3, 128, 8, 14, 110);
    return make_part_a(roll);
}

// Prints one field, by its name in cache_info, or all fields in the order of cache_info ("all").
static void print_info(const cache_info& i, const std::string& field) {
    bool all = field == "all";
    if (all || field == "cache_line_size") std::printf("cache_line_size %u\n", i.cache_line_size);
    if (all || field == "l1_cache_size")   std::printf("l1_cache_size   %u\n", i.l1_cache_size);
    if (all || field == "l1_num_way")      std::printf("l1_num_way      %u\n", i.l1_num_way);
    if (all || field == "l1_latency")      std::printf("l1_latency      %u\n", i.l1_latency);
    if (all || field == "l2_cache_size")   std::printf("l2_cache_size   %u\n", i.l2_cache_size);
    if (all || field == "l2_num_way")      std::printf("l2_num_way      %u\n", i.l2_num_way);
    if (all || field == "l2_latency")      std::printf("l2_latency      %u\n", i.l2_latency);
    if (all || field == "dram_latency")    std::printf("dram_latency    %u\n", i.dram_latency);
}

// Empty if the values describe a cache that make_part_b could build; otherwise the reason.
// Only the rules every cache follows: this does not tell whether the values are right.
static std::string impossible(const cache_info& i) {
    unsigned long sets[2];
    std::uint32_t const size[2] = {i.l1_cache_size, i.l2_cache_size};
    std::uint16_t const ways[2] = {i.l1_num_way, i.l2_num_way};
    for (int l = 0; l < 2; ++l) {
        unsigned long per_set = static_cast<unsigned long>(i.cache_line_size) * ways[l];
        if (per_set == 0 || size[l] % per_set != 0)
            return "l" + std::to_string(l + 1) + "_cache_size is not a multiple of cache_line_size * l" + std::to_string(l + 1) + "_num_way";
        sets[l] = size[l] / per_set;
        if (sets[l] > 0xffff) return "l" + std::to_string(l + 1) + " has too many sets";
    }
    try {
        make_part_b(i.cache_line_size, sets[0], i.l1_num_way, i.l1_latency, sets[1], i.l2_num_way, i.l2_latency, i.dram_latency);
    } catch (const std::exception& e) {
        return e.what();
    }
    return "";
}

static int usage() {
    std::printf("usage: make task3 args=\"read ROLL WORD...\"   (ROLL may be demo; a WORD is ADDR, rm1 ADDR, rm2 ADDR or reset)\n"
                "       make task3 args=\"a\"\n"
                "       make task3 args=\"info ROLL\"\n"
                "       make task3 args=\"probe_parta ROLL\"\n");
    return 2;
}

// Parses an address: decimal, or hex with 0x. Returns false if s is not one.
static bool parse_addr(const char* s, std::uint32_t& a) {
    char* end;
    unsigned long v = std::strtoul(s, &end, 0);
    if (*s == '\0' || *end != '\0' || v > 0xffffffffUL) return false;
    a = static_cast<std::uint32_t>(v);
    return true;
}

int main(int argc, char** argv) {
    try {
        if (argc == 1 || (argc == 2 && std::strcmp(argv[1], "count-removes") == 0)) { // tests
            std::string group;
            unsigned p[8];
            if (!(std::cin >> group)) return 1;
            for (unsigned& v : p) if (!(std::cin >> v)) return 1;
            auto c = make_part_b(p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7]);
            counting_cache w(c.get());
            cache_info i = get_cache_info(&w);
            if (argc == 1) print_info(i, group);
            else std::printf("removes %llu\n", w.removes);
            return 0;
        }

        std::string mode = argv[1];
        if (mode == "read" && argc >= 3) {
            auto c = make_named(argv[2]);
            for (int k = 3; k < argc; ++k) {
                std::uint32_t a;
                if (std::strcmp(argv[k], "reset") == 0) {
                    c->reset();
                    std::printf("reset\n");
                } else if (std::strcmp(argv[k], "rm1") == 0 || std::strcmp(argv[k], "rm2") == 0) {
                    bool l1 = argv[k][2] == '1';
                    if (k + 1 >= argc || !parse_addr(argv[k + 1], a)) { std::printf("%s needs an address after it\n", argv[k]); return 2; }
                    ++k;
                    if (l1) c->remove_from_l1(a);
                    else c->remove_from_l2(a);
                    std::printf("remove_from_l%c(%u)\n", l1 ? '1' : '2', a);
                } else if (parse_addr(argv[k], a)) {
                    std::printf("read(%u) = %u\n", a, c->read(a));
                } else {
                    std::printf("not an address: %s\n", argv[k]);
                    return 2;
                }
            }
            return 0;
        }
        if (mode == "a" && argc == 2) {
            cache_info i = part_a();
            print_info(i, "all");
            std::string why = impossible(i);
            if (!why.empty()) std::printf("these values cannot be a cache: %s\n", why.c_str());
            return 0;
        }
        if (mode == "info" && argc == 3) {
            auto c = make_named(argv[2]);
            counting_cache w(c.get());
            auto t0 = std::chrono::steady_clock::now();
            cache_info i = get_cache_info(&w);
            double ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();
            print_info(i, "all");
            std::printf("(%llu reads, %llu removes, %.1f ms)\n", w.reads, w.removes, ms);
            return 0;
        }
        if (mode == "probe_parta" && argc == 3) {
            // Runs your probe_parta (cache_info.cpp) on an empty cache of ROLL. Not graded.
            auto c = make_named(argv[2]);
            counting_cache w(c.get());
            probe_parta(&w);
            std::printf("(probe_parta made %llu reads)\n", w.reads);
            return 0;
        }
        return usage();
    } catch (const std::exception& e) {
        std::printf("error: %s\n", e.what());
        return 1;
    }
}
